# Written practice: Task 1 introductions and overviews, Task 2 introductions, conclusions, body paragraphs.
VERB = ('a reporting verb (shows, illustrates, compares, gives information about ...)', r'\b(shows?|illustrates?|compares?|presents?|outlines?|depicts?|displays?|gives|provides|summarises?|represents?|describes?|explains?|indicates?|reveals?|tracks?|traces?|examines?|looks at|focuses on)\b', 'must')
NODATA = ('no figures from the data (only years are allowed as numbers)', r'(\b\d{1,3}\b|\b\d{5,}\b|\d\s?%|per cent|percent)', 'not')
NOI = ('no personal opinion in a Task 1 introduction (I / my)', r'\b(I|my|me)\b', 'not')
def intro(i, title, facts, source, typ, where, kws, model):
    ch = [VERB, ('names the type of visual (' + typ[0] + ')', typ[1], 'must')]
    if where: ch.append(('says who or where (' + where[0] + ')', where[1], 'must'))
    ch += [NODATA, NOI]
    return {'id': 't1i-' + i, 'title': title, 'facts': facts, 'source': source, 'n': 4, 'kw': kws, 'checks': ch, 'min': 14, 'max': 55, 'smin': 1, 'smax': 2, 'model': model}
