def ov(i, title, note, head, rows, ch, model, extra=None):
    base = [NODATA, ("an overview signal (Overall, In general, On the whole ...)", r'\b(overall|in general|generally|on the whole|as a whole|the process has|there are)\b', 'must'), ('no "In conclusion" (an overview is not a conclusion)', r'\bin conclusion\b', 'not')]
    return {'id': 't1o-' + i, 'title': title, 'note': note, 'table': {'head': head, 'rows': rows}, 'checks': base + ch, 'kw': [], 'min': 30, 'max': 90, 'smin': 2, 'smax': 4, 'model': model}
RISE = r'\b(rose|rise|risen|rising|increase[ds]?|increasing|grew|grow|grown|growth|upward|climb(ed|ing)?|went up)\b'
FALL = r'\b(fell|fall|fallen|falling|declin\w*|decreas\w*|dropp?ed|drop|reduc\w*|downward|shr[au]nk)\b'
