SIGN = ('a signpost sentence (This essay will ... / I will ...)', r'\b(this essay|I will|I shall|will (identify|examine|outline|suggest|propose|discuss|explore|consider|explain|argue|assess|answer))\b', 'must')
OPIN = ('a clear position (I agree, I disagree, I believe, positive, negative ...)', r"\b(agree|disagree|my view|my opinion|I believe|I would argue|I am convinced|I strongly|I partly|to a large extent|largely|I think|I firmly|I contend|positive|negative|beneficial|harmful|welcome|unwelcome|this essay (will )?(argue|contend|maintain))\b", 'must')
BOTH = ('shows that two views exist (both, some ... others, each ...)', r'\b(both|some|others|each|whereas|while|divided|on the one hand|two (views|positions|sides|perspectives))\b', 'must')
OWN = ('promises or gives your own view', r'\b(my (own )?(view|opinion)|I (will |would |shall )?(believe|think|argue|agree|feel|maintain)|in my (view|opinion)|on balance|this essay (will )?(argue|conclude|maintain))\b', 'must')
POS = ('mentions advantages / benefits', r'\b(advantages?|benefits?|gains|positives?|merits?|upsides?|strengths)\b', 'must')
NEG = ('mentions disadvantages / drawbacks', r'\b(disadvantages?|drawbacks?|downsides?|costs?|negatives?|negative effects|risks?|problems?)\b', 'must')
OUTW = ('answers the outweigh question (outweigh, outnumber, exceed)', r'\b(outweigh\w*|outnumber\w*|exceed\w*|overshadow\w*|greater than|more significant|more important than)\b', 'must')
PROB = ('refers to the problem(s) or cause(s)', r'\b(problem|problems|issue|issues|challenge|cause|causes|reason|reasons|threat|crisis|consequences?|damage|harm|effects?)\b', 'must')
SOLN = ('refers to solution(s) or measures', r'\b(solution|solutions|measure|measures|remedy|remedies|address|tackle|steps|action|propose|recommend\w*|suggest|policies|ways|reverse)\b', 'must')
WHY = ('promises to explain the reasons', r'\b(reasons?|motives?|motivations?|why|causes?|factors|explains?|explain|forces|drivers|behind)\b', 'must')
POSNEG = ('takes a view on positive / negative', r'\b(positive|negative|beneficial|harm\w*|advantageous|damaging|welcome|unwelcome|good thing|bad thing)\b', 'must')
def t2i(i, etype, q, kws, ch, model):
    return {'id': 't2i-' + i, 'etype': etype, 'question': q, 'source': q, 'n': 5, 'kw': kws, 'checks': ch + [SIGN] if False else ch, 'min': 30, 'max': 75, 'smin': 2, 'smax': 3, 'model': model, 'noDigits': True}
