CONCL = ('a concluding signal (In conclusion, Overall, On balance ...)', r'\b(in conclusion|to conclude|in summary|to sum up|overall|all things considered|on balance|ultimately|in short)\b', 'must')
NONEW = ('no new example (for example, for instance, such as)', r'\b(for example|for instance|such as)\b', 'not')
def cc(i, etype, q, summary, kws, model):
    return {'id': 't2c-' + i, 'etype': etype, 'question': q, 'summary': summary, 'kw': kws, 'checks': [CONCL, NONEW, ('no figures', r'\d', 'not')], 'min': 25, 'max': 65, 'smin': 2, 'smax': 3, 'model': model}
